mapper.select:
SELECT w.*, q.id as q_id, q.subject, q.type, q.content, q.option_a, q.option_b,
       q.option_c, q.option_d, q.answer, q.analysis, q.knowledge_point, q.difficulty
FROM wrong_question w
LEFT JOIN question q ON w.question_id = q.id
WHERE w.user_id = #{userId}

    AND q.subject = #{subject}


    AND w.mastered = #{mastered}

ORDER BY w.wrong_time DESC

mapper.update:
UPDATE wrong_question
user_answer = #{userAnswer}, wrong_reason = #{wrongReason}, mastered = #{mastered},
WHERE id = #{id}
